<script setup lang="ts">
import type {PricingOptions} from '../explorationApi'
import {yuanToFen} from '../money'
const model=defineModel<PricingOptions|null>({default:null})
function enable(on:boolean){model.value=on?{party_size:null,vehicle_count:1,driving_basis:'taxi',total_budget_fen:null,per_person_budget_fen:null,per_person_daily:false,dining_per_person_day_fen:null,hard_limit:false}:null}
function amount(key:'total_budget_fen'|'per_person_budget_fen'|'dining_per_person_day_fen',event:Event){const input=event.target as HTMLInputElement;try{const value=yuanToFen(input.value);input.setCustomValidity('');if(model.value)model.value[key]=value}catch(e){input.setCustomValidity((e as Error).message);input.reportValidity()}}
</script>
<template><section class="budget-controls" aria-label="全程费用条件"><label><input type="checkbox" :checked="!!model" @change="enable(($event.target as HTMLInputElement).checked)">核算全程费用</label><template v-if="model"><label>旅行人数<input v-model.number="model.party_size" type="number" min="1" max="50" placeholder="按人费用需要人数"></label><label>全程总预算（元）<input type="text" inputmode="decimal" :value="model.total_budget_fen==null?'':model.total_budget_fen/100" @change="amount('total_budget_fen',$event)"></label><label>人均预算（元）<input type="text" inputmode="decimal" :value="model.per_person_budget_fen==null?'':model.per_person_budget_fen/100" @change="amount('per_person_budget_fen',$event)"></label><label><input v-model="model.per_person_daily" type="checkbox">人均预算按每天计算</label><label>每人每天餐费预留（元）<input type="text" inputmode="decimal" :value="model.dining_per_person_day_fen==null?'':model.dining_per_person_day_fen/100" placeholder="选填，替代路线内餐饮估价" @change="amount('dining_per_person_day_fen',$event)"></label><label>驾车费用口径<select v-model="model.driving_basis"><option value="taxi">打车（估价按车计）</option><option value="self_drive">自驾（油费、停车费待核对）</option></select></label><label v-if="model.driving_basis==='taxi'">打车车辆数<input v-model.number="model.vehicle_count" type="number" min="1" max="20"></label><label><input v-model="model.hard_limit" type="checkbox">仅接受费用齐全且不超过预算的方案</label><p>预算按整趟核算；住宿来自已确认的房型报价或手填价格。空缺费用会列出。</p></template></section></template>
<style scoped>.budget-controls{padding:12px 0;border-top:1px solid #ded4c2;display:grid;gap:12px}.budget-controls input[type=checkbox]{display:inline-block;width:18px;min-height:18px;margin-right:8px;vertical-align:middle}.budget-controls p{font-size:12px;line-height:1.7}</style>
